OOD_SLICES["code"] = [
    "# Merge sort: split the list in half, sort each half recursively,\n    # then merge the two sorted halves back together in linear time.\n    def merge_sorted(left, right):\n    merged = []\n    i = j = 0\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            merged.append(left[i])\n            i += 1\n        else:\n            merged.append(right[j])\n            j += 1\n    merged.extend(left[i:])\n    merged.extend(right[j:])\n    return merged\n\n\ndef merge_sort(values):\n    if len(values) <= 1:\n        return list(values)\n    mid = len(values) // 2\n    left = merge_sort(values[:mid])\n    right = merge_sort(values[mid:])\n    return merge_sorted(left, right)\n\n\nif __name__ == '__main__':\n    data = [9, 3, 7, 1, 8, 2, 6, 4, 5]\n    print(merge_sort(data))\n    print(merge_sort([]))\n    print(merge_sort([42]))",
    "import csv\nimport sys\nfrom collections import Counter\n\n\ndef read_counts(path):\n    counts = Counter()\n    with open(path, newline='', encoding='utf-8') as handle:\n        reader = csv.DictReader(handle)\n        for row in reader:\n            status = row.get('status', '').strip().lower()\n            if status:\n                counts[status] += 1\n    return counts\n\n\ndef main(argv):\n    if len(argv) != 2:\n        print('usage: count_status.py <file.csv>', file=sys.stderr)\n        return 2\n    counts = read_counts(argv[1])\n    total = sum(counts.values())\n    for status, number in counts.most_common():\n        share = number / total if total else 0.0\n        print(f'{status}: {number} ({share:.1%})')\n    print(f'total rows: {total}')\n    return 0\n\n\nif __name__ == '__main__':\n    raise SystemExit(main(sys.argv))",
    "# A small least-recently-used cache built on plain dictionaries.\n    # It keeps the most recently touched keys and evicts the oldest\n    # entry whenever the capacity would be exceeded by a new insert.\n    class LRUCache:\n    def __init__(self, capacity):\n        if capacity <= 0:\n            raise ValueError('capacity must be positive')\n        self.capacity = capacity\n        self._order = {}\n        self._values = {}\n\n    def get(self, key):\n        if key not in self._values:\n            return None\n        self._order[key] = self._order.get(key, 0) + 1\n        self._touch(key)\n        return self._values[key]\n\n    def put(self, key, value):\n        self._values[key] = value\n        self._touch(key)\n        while len(self._values) > self.capacity:\n            oldest = min(self._order, key=self._order.get)\n            del self._values[oldest]\n            del self._order[oldest]\n\n    def _touch(self, key):\n        stamp = max(self._order.values(), default=0) + 1\n        self._order[key] = stamp\n\n    def __len__(self):\n        return len(self._values)",
    "def fibonacci(n):\n    if n < 0:\n        raise ValueError('n must be non-negative')\n    a, b = 0, 1\n    for _ in range(n):\n        a, b = b, a + b\n    return a\n\n\ndef is_prime(number):\n    if number < 2:\n        return False\n    if number == 2:\n        return True\n    if number % 2 == 0:\n        return False\n    limit = int(number ** 0.5) + 1\n    divisor = 3\n    while divisor < limit:\n        if number % divisor == 0:\n            return False\n        divisor += 2\n    return True\n\n\nprimes = [n for n in range(2, 100) if is_prime(n)]\nprint('primes below 100:', primes)\nprint('fibonacci(20):', fibonacci(20))",
    "# Fetch a JSON document over plain HTTPS and summarise a list of items.\n    # The helper raises a clear error when the server answers with any\n    # status other than success, so callers can distinguish network faults.\n    import json\nimport urllib.request\n\n\ndef fetch_json(url, timeout=10):\n    request = urllib.request.Request(url, headers={'Accept': 'application/json'})\n    with urllib.request.urlopen(request, timeout=timeout) as response:\n        if response.status != 200:\n            raise RuntimeError(f'unexpected status {response.status}')\n        payload = response.read()\n    return json.loads(payload.decode('utf-8'))\n\n\ndef summarize(items):\n    names = sorted(item.get('name', 'unknown') for item in items)\n    return {'count': len(items), 'names': names}\n\n\nif __name__ == '__main__':\n    data = fetch_json('https://example.com/api/items')\n    print(json.dumps(summarize(data), indent=2))",
    "def binary_search(sorted_values, target):\n    low = 0\n    high = len(sorted_values) - 1\n    steps = 0\n    while low <= high:\n        steps += 1\n        mid = (low + high) // 2\n        value = sorted_values[mid]\n        if value == target:\n            return mid, steps\n        if value < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1, steps\n\n\ndef linear_search(values, target):\n    for index, value in enumerate(values):\n        if value == target:\n            return index\n    return -1\n\n\nsample = [3, 8, 11, 19, 27, 34, 42, 55, 61, 78]\nprint(binary_search(sample, 34))\nprint(binary_search(sample, 99))\nprint(linear_search(sample, 19))",
]

OOD_SLICES["recipe"] = [
    "To make a proper mushroom risotto, start by warming about a litre of vegetable stock in a saucepan and keeping it at a gentle simmer. Finely chop one onion and two cloves of garlic, then soften them in olive oil in a wide, heavy pan over medium heat. Add three hundred grams of sliced chestnut mushrooms and cook until they release their liquid and begin to brown at the edges. Stir in three hundred grams of carnaroli rice and toast it for two minutes until the grains turn translucent. Pour in a glass of dry white wine and let it bubble away. Then add the hot stock one ladle at a time, stirring often and waiting until each ladle is absorbed before adding the next. After about eighteen minutes the rice should be creamy but still firm in the middle. Take the pan off the heat, stir in a knob of cold butter and a handful of grated parmesan, cover and rest for two minutes before serving with extra parmesan and cracked black pepper.",
    "This tomato soup is best made with ripe summer tomatoes, but good tinned ones work in winter. Halve a kilo of tomatoes and roast them with a sliced onion, four garlic cloves and a drizzle of olive oil at two hundred degrees for thirty-five minutes until the edges char slightly. Tip everything, juices included, into a large pot with half a litre of vegetable stock and a pinch of sugar. Simmer for fifteen minutes, then blend until completely smooth, working in batches if your blender is small. Pass the soup through a sieve if you want a silky finish, though it is perfectly good rustic. Season with salt, pepper and a splash of sherry vinegar to lift the flavour. Serve hot with torn basil leaves, a swirl of cream or olive oil, and thick slices of toasted sourdough rubbed with garlic for dipping.",
    "For a weeknight chicken traybake, preheat the oven to two hundred degrees and line a large roasting tin with baking paper. Cut four chicken thighs, two red peppers, one red onion and a courgette into rough chunks and spread them in the tin. Add a tin of drained chickpeas, a handful of cherry tomatoes, four unpeeled garlic cloves and a few sprigs of rosemary. Drizzle generously with olive oil, scatter over a teaspoon each of smoked paprika and ground cumin, and season well. Toss everything together with your hands so the spices coat evenly. Roast for forty minutes, turning once halfway, until the chicken skin is crisp and the vegetables are soft and caramelised at the edges. Squeeze half a lemon over the top before serving, and eat with crusty bread or couscous to mop up the juices.",
    "A good loaf of no-knead bread needs time more than effort. In a large bowl, mix five hundred grams of strong white flour with ten grams of salt and two grams of instant yeast. Add three hundred and fifty millilitres of lukewarm water and stir with a wooden spoon until you have a shaggy, sticky dough with no dry flour left. Cover the bowl with a tea towel and leave it on the counter for twelve to eighteen hours. The dough will rise and develop bubbles. Turn it out onto a floured surface, fold it over itself a few times, and shape it into a round. Let it rest for thirty minutes while the oven heats to two hundred and thirty degrees with a lidded pot inside. Bake covered for thirty minutes, then uncovered for fifteen more until the crust is deep golden and the loaf sounds hollow when tapped underneath.",
    "These oat pancakes make a filling breakfast and freeze well. Whisk two eggs with two hundred millilitres of milk and a tablespoon of honey in a jug. In a separate bowl, combine one hundred and fifty grams of rolled oats, a teaspoon of baking powder, a pinch of salt and a teaspoon of cinnamon. Pour the wet ingredients into the dry ones and stir until just combined, then leave the batter to rest for ten minutes so the oats soften. Heat a non-stick pan over medium heat with a little butter, and ladle in small rounds of batter. Cook for two to three minutes until bubbles appear on the surface and the edges look set, then flip and cook for another minute. Keep the finished pancakes warm under a tea towel while you cook the rest. Serve with sliced banana, a spoonful of yoghurt and a drizzle of maple syrup.",
    "To pickle red onions, peel and thinly slice two large red onions into rings. Pack them loosely into a clean jar with a teaspoon of black peppercorns and one bay leaf. In a small saucepan, bring two hundred millilitres of apple cider vinegar, two hundred millilitres of water, two tablespoons of sugar and one tablespoon of salt to a boil, stirring until the sugar dissolves. Pour the hot brine over the onions, pressing them down so they are fully submerged. Leave the jar to cool to room temperature, then seal it and refrigerate. The onions will be bright pink and ready to eat after a few hours, but they taste best after a day or two. They keep in the fridge for up to three weeks and are excellent on tacos, grain bowls, sandwiches and grilled meats.",
]

